/**
 * IPC contract between the Electron entries: `desktop/main` registers these channels,
 * `desktop/preload`'s bridge invokes them. Namespaced so they never collide with an app's own IPC
 * handlers.
 */
export const MANAGED_AUTH_IPC = {
  openExternal: "managed-auth:open-external",
  redirectTarget: "managed-auth:redirect-target",
  deepLink: "managed-auth:deep-link",
} as const;
